You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

Let $[r]$ denote the set $\{1,\ldots,r\}$. We use the notation $x \in (1\pm \eps)\cdot y$ as a shorthand for $(1-\eps)\cdot y \leq x \leq (1+\eps)\cdot y$.

Let $G = (V,E)$ be an undirected simple graph over $n$ vertices.
For a vertex $v$ let $d(v)$  denote the degree of $v$. 

Let $\Cyk$  denote the cycle over $k$ vertices. When referring to a subgraph of $G$ that is a cycle, we use
the notation $(v_1,\dots,v_k,v_1)$ (where $\big\{\{v_i,v_{i+1}\}:i\in [k-1]\big\}\cup \big\{\{v_k,v_1\}\big\} \subseteq E$).

 A \emph{motif} $\F$ is a graph over $k$ vertices (which is known and considered to be small). 

\begin{definition}[Copies of a motif $\F$]\label{def:copy}
 For a graph $G$ and a motif $\F$,  we say that a subgraph $\f$ of $G$   is a \textsf{copy} of $\F$ in $G$ if $\f$ is isomorphic to $\F$.
\end{definition}

\begin{definition}[Hamiltonian cycles of a copy]\label{def:Ham}
For a copy $\f$ of $\F$ in $G$, let $\ham(\f)$ denote the set of different copies of $\Cyk$ in $\f$ (i.e., Hamiltonian cycles of $\f$). 
~Since $|\ham(\f)|$ is the same for all copies $\f$ of $\F$, we denote this value by $\hF$. 
\end{definition}

\begin{definition}[Number of copies in a subgraph that contain a given cycle]
\label{def:nF}
 For  a graph $Q$, a motif $\F$ and a cycle $\Cy\in \ham(Q)$, each with $k = |V(\F)|$ vertices, we let $\countF(Q, \Cy)$ denote the number of different  copies of $\F$ in $Q$ that include the cycle $\Cy$.     

We note that for a fixed $\F$, $\countF(Q, \Cy)$ is maximized when $Q$ is a clique over $k= |V(\F)|$ vertices and $\Cy$ is some Hamiltonian cycle of $Q$. 
We denote this value by $\kappaF$.\footnote{\label{foot:kappaF} Observe that $\kappaF$ ranges between $1$ and $k!$.}
\end{definition}

\begin{definition}[An $(\oeps,\ogamma,\om)$-degrees-typical multiset and data structure]
\label{def:good-DS}
For a graph $G=(V,E)$ over $n$ vertices and parameters $\oeps \in (0,\frac{1}{2})$ and $\ogamma,\om \in \mathbb{N}^+$, 
    we say that a multiset  $S$ of vertices from $V$ is \textsf{$(\oeps,\ogamma,\om)$-degrees-typical} with respect to $G$, if the following two conditions hold:
    \begin{enumerate}

            \item For every $v\in V$ with $d(v)> \ogamma$, we have that $d_S(v)
                \in (1\pm\oeps)\frac{d(v)}{n}$.

                \item Letting $m(S)=\sum_{u\in S}d(u)$ and $\od = \frac{\om}{n}$,
        we have that $m(S)\leq 2\cdot |S|\cdot \od$. 
    \end{enumerate}
   A data structure $\calD$ is \textsf{$(\oeps,\ogamma,\om)$-degrees-typical} with respect to $G$, if for some multiset $S$ that is
   $(\oeps,\ogamma,\om)$-degrees-typical with respect to $G$, the data structure $\calD$  supports sampling each vertex $u\in S$ with probability $\frac{d(u)}{2\od|S|}$ in constant time. 
   If $G$ is clear from the context, then we shall just say that $\calD$ is $(\oeps,\ogamma,\om)$-degrees-typical.
\end{definition}

\begin{lemma}[Sampling medium-high vertices]\label{lem:sampHeavyVertex}
Let $G$ be a graph 
and let  $\oeps \in (0,\frac{1}{2})$ and $\ogamma,\om \in \mathbb{N}^+$. 
The procedure \sampHighVertex\ is given query access to $G$ and
 an $(\oeps,\ogamma,\om)$-degrees-typical data structure $\calD$ (w.r.t. $G$), and satisfies the following. 
 \begin{itemize}

  \item 
 Each invocation of \sampHighVertex$(\calD,\ogamma)$ either outputs a vertex $v$ or fails. The distribution on output vertices is such that every  vertex $v$ for which
$d(v)> \ogamma$ is returned with probability in $(1\pm\oeps)\frac{d(v)}{2\om}$ and every vertex $v$ with $d(v)\leq\ogamma$ is returned with probability $0$. 

\sloppy
\item The query complexity and running time  of (a single invocation of) \sampHighVertex{} are $O(1)$. 
\end{itemize}
\end{lemma}

Recall that a low copy of $\F$ in $G$ is a copy 
whose vertices all have degree at most $\ogamma$ (for a given parameter $\ogamma$).

\alg{alg:sampLowCopies}{
	{\bf \sampLowCopies}$\;(\F,\ogamma)$ 		\begin{enumerate}[itemsep=.2em, leftmargin=*]
		\item Sample a vertex $v_1 \in V$ uniformly at random. If $d(v_1) > \ogamma$, then \textbf{return} \emph{fail}.\label{step:sample-uniform}
    \item For $i=1$ to $k-1$:
    \begin{enumerate}[itemsep=.2em]
          \item Choose an index $j\in [\ogamma]$ u.a.r.
          If $j > d(v_i)$, then \textbf{return} \emph{fail}. Otherwise,
          query for $v_i$'s $j\th$ neighbor and let  $v_{i+1}$ denote the  neighbor returned. 
          \label{step:sample-neighbor-light}
          \item If $d(v_{i+1}) > \ogamma$, then \textbf{return} \emph{fail}. 
    \end{enumerate}
      \item If $v_i = v_{i'}$ for some $1 \leq i < i' \leq k$ or $\{v_k, v_1\}\notin E$,  then \textbf{return} \emph{fail}. \label{step:check-low}   \newcomment{Verify that no vertex is sampled twice and that the path forms a cycle.}
      \item \label{step:select-low-copy} Let $\Cy$ denote the cycle $(v_1, \ldots v_k, v_1)$, and  let $\Q$ be the subgraph induced by the set of vertices  $\{v_1,\dots,v_k\}$. If $\Q$ contains at least one copy of $\F$, then either select one such copy $\f$ or \textbf{return} \emph{fail}, where for each copy, the probability that it is selected is $1/\kappaF$. 
      \newcomment{Recall: $\kappaF$ is defined in Definition~\ref{def:nF}}
                       \item Return $\f$ with probability $\frac{1}{\hF\cdot 2k}$ and with probability $1-\frac{1}{\hF\cdot 2k}$. 
      \textbf{return} \emph{fail}. \newcomment{Recall: $\hF$ is defined in Definition~\ref{def:Ham}} \label{step:check-iso}  
      \label{step:return-low-copy}
	\end{enumerate}
}

\begin{lemma}\label{lem:samp-low}
    Algorithm \sampLowCopies$(\F,\ogamma)$ either returns a  copy of $\F$ in $G$ such that all vertices in the copy have degree at most $\ogamma$ or fails. Furthermore, each  such copy is returned  with probability $\frac{1}{n\cdot \ogamma^{k-1} \cdot \kappaF}$.
    The query complexity of the algorithm is $O(k^2)$, 
    and the running time is upper bounded by $O(k!\cdot k^2)$.
\end{lemma}

A mixed copy of $\F$ in $G$ is a copy that contains at least one vertex with degree exceeding $\ogamma$.

\begin{definition}[paths cover] \label{def:cover}
 Let 
  $\Cy = (u_1,\dots,u_k,u_1)$ be a copy of $\Cyk$ in $G$.
 For positive integers $\ogamma$ and $\om$
 such that $\ogamma \leq \sqrt{\om}$,
 we say that a sequence of $r \geq 1$ paths 
$\langle \pi_1,\dots,\pi_r \rangle$
 \textsf{covers} $\Cy$ with respect to $\ogamma$ and $\om$, if the following conditions hold.
 \begin{enumerate}
     \item Every vertex in $\Cy$ belongs to exactly one of the $r$ paths, and every edge in each of the paths belongs to $\Cy$.
     \item For every $q\in [r-1]$ there is an edge between the last vertex in $\pi_q$ and the first vertex in $\pi_{q+1}$, and there is also an edge between the last vertex in $\pi_r$ and the first vertex in $\pi_1$.
     \item For every $q \in [r]$, 
 the first vertex in $\pi_q$ has degree greater than $\ogamma$, and if $|\pi_q|=1$, then it has degree greater than $\sqrt{\om}$. Every other vertex on the path
has degree at most $\sqrt{\om}$.


 \end{enumerate}
  \end{definition}

\begin{definition}[fitting]\label{def:fitting}
 Let $\Cy = (v_1,\dots,v_k,v_1)$ be a copy of $\Cyk$ in $G$ and let $\ogamma$ and $\om$ be positive integers such that $\ogamma \leq \sqrt{\om}$.
 For a sequence of positive integers $\vec{x} = \langle x_1,\dots, x_r\rangle$ such that $\sum_{q=1}^r x_q = k$, we say that $\vec{x}$ \textsf{fits} $\Cy$ if there exist a sequence of paths $\pi_1,\dots,\pi_r$ that covers $\Q$ such that $|\pi_q|=x_q$ for every $q\in [r]$. We say in such a case that $\pi_1,\dots,\pi_r$ \textsf{corresponds} to $\vec{x}$.

    We denote by $\nu_{\vec{x}}(\Cy)$ the number of different sequences 
    of paths
    covering $\Cy$ that correspond to $\vec{x}$ and by $\nu(\Cy)$, the sum over all $\vec{x}$ that fit $\Cy$\tnew{,} of $\nu_{\vec{x}}(\Cy)$. 
 \end{definition}

\begin{definition}[number of fittings]\label{def:number-fittings}
For a copy $\f$ of $\F$ in $G$, we define $\nu(\f) = \sum_{\Cy \in \ham(\f)} \nu(\Cy)$.
\end{definition}

\alg{alg:sampHMCopies}{
	{\bf \sampHMCopies}$\;(\F,\ogamma,\om,\calD)$ 		\begin{enumerate}[itemsep=.2em, leftmargin=*]
		\item \label{step:select-vecx} Select, u.a.r., a sequence $\vec{x} = \langle x_1,\dots,x_r\rangle$ of positive integers such that $\sum_{q=1}^r x_q =k$. 
        \item For ($q=1$ to $r$) do:\label{step:select-path}
           \begin{enumerate}[itemsep=.2em]
              \item \label{step:select-hm} Invoke \sampHighVertex$(\calD,\ogamma)$. 
              If no vertex is returned, then
              \textbf{return} \emph{fail}.
            Otherwise, denote the returned vertex   by $v_{q,1}$.                                     
              \item \label{step:x-q-1} If $x_q = 1$:
                     \begin{itemize}
                      \item  If $d(v_{q,1}) \leq \sqrt{\om}$, then \textbf{return} \emph{fail}, 
                                        otherwise \textbf{return} \emph{fail} with probability $1-\frac{\sqrt{\om}}{d(v_{q,1})}$. \newcomment{If the path contains a single vertex, then it must have degree greater than $\sqrt{\om}$. 
                                        }
                  \end{itemize}  
                  \item \label{step:first-edge} If $x_q > 1$, then choose an index $j \in [d(v_{q,1})]$ and query for $v_{q,1}$'s $j\th$ neighbor. Let this vertex be denoted $v_{q,2}$. If $d(v_{q,2}) > \sqrt{\om}$, then
              \textbf{return} \emph{fail}, otherwise,  \textbf{return} \emph{fail} with probability $1/2$.
              \newcomment{Sample a uniform neighbor of $v_{q,1}$ and verify it does not have high degree.}
             \item \label{step-other-edges} For ($y = 2$ to $x_q-1$) do
              \begin{itemize}
                \item Choose an index $j\in [\sqrt{\om}]$  u.a.r. 
                                               If $j>d(v_{q,y})$, then \textbf{return} \emph{fail}. 
                                Otherwise query for $v_{q,y}$'s $j\th$ neighbor and let $v_{q,y+1}$ denote the neighbor returned.  If $d(v_{q,y+1}) > \sqrt{\om}$, then
              \textbf{return} \emph{fail}, otherwise,  \textbf{return} \emph{fail} with probability $1/2$. 
              \newcomment{Sample a uniform neighbor of $v_{q,1}$, such that each is sampled w.p. $\frac{1}{2\sqrt m}$. If the sampled neighbor is high, then fail.}
              \label{step:hm-sample-neighbor-light}
               \end{itemize}
          \end{enumerate}
      \item \label{step:check-cycle} If $v_{q,y} = v_{q',y'}$ for any $(q,y) \neq (q',y')$
      or $(v_{q,x_q},v_{q+1,1}) \notin E$ for some $1\leq q \leq r-1$, or
            $(v_{r,x_r}, v_{1,1})\notin E$, then \textbf{return} \emph{fail}. \newcomment{Verify that no vertex is sampled twice and that the sampled path cover results in a cycle.}
      \item \label{step:select-hm-copy} Let $\Q$ be the induced subgraph over the vertices $v_{1,1},\dots,v_{r,x_r}$. 
     If $\Q$ contains at least one copy of $\F$, then either select one such copy $\f$ or \textbf{return} \emph{fail}, where for each copy, the probability that it is selected is $1/\kappaF$.  \newcomment{Recall: $\kappaF$ is defined in Definition~\ref{def:nF}}
                       \item \label{step:return-hm-copy} Return $\f$ with probability $\frac{1}{\nu(\f)}$, and with probability $1-\frac{1}{\nu(\f)}$ \textbf{return} \emph{fail}. \newcomment{Recall:  $\nu(f)$ is defined in Definition~\ref{def:number-fittings}.}
  \end{enumerate}

 }

\alg{alg:sample-copy}{
	{\bf \SampleWithEstimate}$\;(n, \F,\ogamma, \om, \calD)$ 
    		\begin{enumerate}[, leftmargin=*]
 \item Set $\Bl =  n\cdot \ogamma^{k-1} \cdot \kappaF$,\; $\Bmh =  2^k\cdot \om^{k/2} \cdot \kappaF$ \tnew{and $B=\Bl+\Bmh$}.

       \item        With probability $\frac{\Bl}{B}$ invoke \sampLowCopies$(\F,\ogamma)$ and with probability $\frac{\Bmh}{B}$ invoke \sampHMCopies$(\F,\ogamma,\om,\calD)$.
       \item If a copy of $\F$ was returned, then return this copy. Otherwise \textbf{return} \emph{fail}. 
       \end{enumerate}
 }


